import { report_warning } from '../diagnostics'

export const KWZ_REAL_PUB_SPKI_B64 =
  ''

export const KWZ_REAL_KEY_PKCS8_B64 =
  ''

export const PPM_REAL_KEY_PKCS8_B64 =
  ''

export const PPM_REAL_PUB_SPKI_B64 =
  'MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQDCPLwTL6oSflv+gjywi/sM0TUB90xqOvuCpjduETjPoN2FwMebxNjdKIqHUyDu4AvrQ6BDJc6gKUbZ1E27BGZoCPH49zQRb+zAM6M9EjHwQ6BABr0u2TcF7xGg2uQ9MBWz9AfbVQ91NjfrNWo0f7UPmffv1VvixmTk1BCtavZxBwIDAQAB'

type KeyParams = { name: string, hash: string }

async function importB64Key(b64: string | null, params: KeyParams, usages: KeyUsage[], fmt: 'pkcs8' | 'spki'): Promise<CryptoKey | null> {
  if (!b64 || typeof crypto === 'undefined' || !crypto.subtle) return null
  try {
    const bin = atob(b64)
    const bytes = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
    return await crypto.subtle.importKey(fmt, bytes, { name: params.name, hash: params.hash }, false, usages)
  } catch (error) {
    report_warning('署名鍵の読み込みに失敗しました', error)
    return null
  }
}

export type RealKey = {
  priv: () => Promise<CryptoKey | null>
  pub: () => Promise<CryptoKey | null>
  reset: () => void
  override: (b64: string) => void
  active: () => boolean
}

export function makeRealKey(privB64: string, pubB64: string | null, params: KeyParams): RealKey {
  let privPromise: Promise<CryptoKey | null> | null = null
  let pubPromise: Promise<CryptoKey | null> | null = null
  let userB64: string | null = null
  return {
    priv() {
      if (!privPromise) privPromise = importB64Key(userB64 || privB64, params, ['sign'], 'pkcs8')
      return privPromise
    },
    pub() {
      if (!pubPromise) pubPromise = importB64Key(pubB64, params, ['verify'], 'spki')
      return pubPromise
    },
    reset() {
      privPromise = null
    },
    override(b64: string) {
      userB64 = b64
      privPromise = null
    },
    active() {
      return !!(userB64 || privB64)
    },
  }
}
